335: /// `vector_intra_slice_unzip`: the elements inside `group_axis`, which is the branch group size.
336: ///
337: /// Group 0 waits in the VE register-file cache while group 1 streams in, so one group must fit it.
338: pub fn config_vector_intra_slice_unzip(input: VectorIntraSliceUnzipInput) -> Result<usize, VectorError> {
339:     let VectorIntraSliceUnzipInput {
340:         group_axis,
341:         in_time,
342:         in_packet,
343:     } = input;
344:     let stream = in_time.pair(in_packet);
345:     let mut group_volume = 1;
346:     for axis in axis_leaves(&stream) {
347:         if axis.idents().contains(&group_axis) {
348:             let max_volume = length_from_bytes(VE_ELEMENT_BITS, VRF_CACHE_BYTES)
349:                 .expect("the fixed VRF cache size contains whole VE elements");
350:             if group_volume > max_volume {
351:                 return Err(VectorError::UnzipGroupTooLarge {
352:                     group_axis,
353:                     volume: group_volume,
354:                     max_volume,
355:                 });
356:             }
357:             return Ok(group_volume);
358:         }
359:         // Padded extents: the stream walks the padding cells too.
360:         group_volume *= axis.size();
361:     }
362:     Err(VectorError::UnzipGroupAxisMissing { group_axis, stream })
